export const meta = {
  name: 'security-audit',
  description: 'Detect stack → set up an ignored run dir and resolve the pinned skill → reconnaissance → coverage ledger → hunting waves with coverage critics → independent static verification → validated findings → target-neutral report. Never runs target code.',
  whenToUse: 'When a codebase or a scope needs a deep, coverage-led security audit with independently verified findings (an explicit audit, pen-test or full security review; a quick checklist is /security-scan). Pass { scope:{paths:[...]} | {gitRange:"<base>..HEAD"}, repo, profile:"quick"|"standard"|"deep", budget, maxUnits, outputDir, models }. Run artifacts go to a VCS-ignored run dir; a target-neutral summary is saved to .ai/reports/. A lead is confirmed only when two independent verifiers agree on static source evidence; anything that needs running the code stays needs_validation.',
  phases: [
    { title: 'Detect', detail: 'Identify the repo layout and pick the target repo (gate commands are recorded, never run)', model: 'sonnet' },
    { title: 'Setup', detail: 'Git check, ignored run dir, revision stamp, pinned skill resolution, budget gate', model: 'haiku' },
    { title: 'Recon', detail: 'Four reconnaissance agents map the product, principals, entry surfaces and local visibility', model: 'sonnet' },
    { title: 'Plan', detail: 'Architecture summary and the deterministic coverage ledger, written and validated', model: 'opus' },
    { title: 'Hunt', detail: 'Coverage-led hunting waves, one hunter per ledger unit', model: 'sonnet' },
    { title: 'Critic', detail: 'A fresh coverage critic after each wave and a final-clean pass', model: 'opus' },
    { title: 'Validate', detail: 'Two fresh verifier votes per candidate and a tie-breaker on disagreement', model: 'opus' },
    { title: 'Findings', detail: 'findings.json, both upstream validators, one repair, target tamper check', model: 'sonnet' },
    { title: 'RecordVerify', detail: 'A fresh agent checks every retained record', model: 'opus' },
    { title: 'Report', detail: 'REPORT.md, FINDINGS-DETAIL.md, NEEDS-VALIDATION.md and the committed summary', model: 'sonnet' },
  ],
}

